define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_2.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e9829","topics":[]},{"title":"<span class=\"ph\">Shutting down the host computer<\/span>","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e9931","topics":[]},{"title":"Applying LOTO - Main Disconnect Panel (MDP)","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_Victor_Prime_2.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e10034","topics":[]},{"title":"Doing a check of the overload and short circuit trip settings for the <span class=\"ph\">Power Distribution Unit (PDU)<\/span> input circuit breaker","shortdesc":"<p class=\"shortdesc\">Do a check of the <span class=\"ph\">PDU<\/span> settings for various voltages.<\/p>","href":"t_ConfirmingOverloadAndShortCircuitTripSettingsForPDUInputCircuitBreaker.html","attributes":{"data-id":"id_2001392"},"menu":{"hasChildren":false},"tocID":"id_2001392-d46e10138","topics":[]},{"title":"Setting the <span class=\"ph\">Power Distribution Unit (PDU)<\/span> breakers and sub breakers","shortdesc":"<p class=\"shortdesc\">Complete these steps to finish the first portion of the power on procedure.<\/p>","href":"t_SettingTheISCSPDUBreakersAndSubBreakers.html","attributes":{"data-id":"id_2003027"},"menu":{"hasChildren":false},"tocID":"id_2003027-d46e10246","topics":[]},{"title":"Integrated Cooling Cabinet (ICC) power on procedure","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_ICCPowerONProcedure_Victor.html","attributes":{"data-id":"id_2042349"},"menu":{"hasChildren":false},"tocID":"id_2042349-d46e10351","topics":[]},{"title":"18KW chiller power on procedure","shortdesc":"<p class=\"shortdesc\"\/>","href":"t_18KWChillerPowerOn.html","attributes":{"data-id":"id_2042359"},"menu":{"hasChildren":false},"tocID":"id_2042359-d46e10452","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the beginning of some procedures and at the end of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_Parent_2.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e10553","topics":[]}]});